11	// View rend l'interface : header, ligne de titre, viewport, footer (Rule 124).
12	// Un overlay ouvert remplace le tout.
13	func (a *App) View() string {
14		if overlay := a.activeOverlay(); overlay != "" {
15			return lipgloss.Place(a.width, a.height, lipgloss.Center, lipgloss.Center, overlay,
16				lipgloss.WithWhitespaceBackground(theme.ColorBackground))
17		}
18	
19		inner := a.renderHeader() + "\n" + a.renderTitleLine() + "\n" + a.renderBody()
20		if footer := a.renderViewFooter(); footer != "" {
21			inner += "\n" + footer
22		}
23	
24		return lipgloss.Place(a.width, a.height, lipgloss.Left, lipgloss.Top, inner,
25			lipgloss.WithWhitespaceBackground(theme.ColorBackground))
26	}
27	
28	// activeOverlay returns the overlay to draw instead of the view, or "" when
29	// there is none. The order matches the one handleKeyMsg dispatches in, so the
30	// overlay holding the keyboard is the one on screen.
31	func (a *App) activeOverlay() string {
32		switch {
33		case a.showHelp:
34			return a.renderHelpOverlay()
35		case a.showContextList:
36			return a.renderContextListOverlay()
37		}
38		return ""
39	}
40	
41	// renderBody fills the viewport with the active view's content, padded to the
42	// full inner width so no line shows the terminal's own background (Rule 115).
43	func (a *App) renderBody() string {
44		content := "View not found: " + string(a.currentView)
45		if view, ok := a.views[a.currentView]; ok {
46			content = view.View()
47		}
48	
49		innerWidth := a.viewport.Width - 2 // -2 pour les bordures
50		a.viewport.SetContent(lipgloss.NewStyle().
51			Background(theme.ColorBackground).
52			Foreground(theme.ColorText).
53			Width(innerWidth).
54			Render(content))
55	
56		body := a.viewport.View()
57	
58		// Rule 136: with a filter bar below it, the viewport's bottom corners become
59		// T-junctions so the two form one closed rectangle.
60		if view, ok := a.views[a.currentView]; ok {
61			if fbv, ok := view.(FilterBarView); ok && fbv.FilterBarVisible() {
62				body = replaceViewportBottomCorners(body)
63			}
64		}
65		return body
66	}
67	
68	// renderTitleLine draws the viewport's top border carrying the view's title.
69	func (a *App) renderTitleLine() string {
70		if view, ok := a.views[a.currentView]; ok {
71			if hv, implements := view.(HeaderView); implements {
72				return theme.RenderBorderTitle(hv.GetTitle(), a.width)
73			}
74		}
75		return theme.RenderBorderTitle("", a.width)
76	}
77	
78	// renderViewFooter returns the active view's footer, or "" when it has none.
79	func (a *App) renderViewFooter() string {
80		if view, ok := a.views[a.currentView]; ok {
81			if fv, ok := view.(FooterView); ok {
82				return fv.RenderFooter(a.width)
83			}
84		}
85		return ""
86	}
87	
88	// replaceViewportBottomCorners turns the viewport's bottom └ and ┘ into the
89	// T-junctions ├ and ┤, so the filter bar rendered below it in the footer joins
90	// the border into one closed rectangle instead of two stacked boxes.
91	func replaceViewportBottomCorners(body string) string {
92		lastNewline := strings.LastIndex(body, "\n")
93		if lastNewline == -1 {
94			return body
95		}
96		lastLine := body[lastNewline+1:]
97		lastLine = strings.Replace(lastLine, "└", "├", 1)
98		lastLine = strings.Replace(lastLine, "┘", "┤", 1)
99		return body[:lastNewline+1] + lastLine
100	}
