191	// requestResize asks for a fresh layout at the current size. Every handler that
192	// changes what the window holds returns one, because the viewport height is
193	// budgeted against the header and the active view's footer.
194	func (a *App) requestResize() tea.Cmd {
195		return func() tea.Msg {
196			return tea.WindowSizeMsg{Width: a.width, Height: a.height}
197		}
198	}
