200	func (a *App) resize(width, height int) {
201		a.width = width
202		a.height = height
203	
204		// Rule 124: footer height is deducted from the viewport (tabs + optional info line)
205		footerHeight := a.getFooterHeight()
206		a.lastFooterHeight = footerHeight
207	
208		headerHeight := lipgloss.Height(a.renderHeader())
209		availableHeight := height - headerHeight - footerHeight
210		a.viewport.Width = width
211		a.viewport.Height = availableHeight - 1 // -1 for the custom title border line
212		a.viewport.Style = viewportStyle()
213	
214		// Propager à la vue active. Le viewport a 1 bordure (bottom only), la vue
215		// doit connaître la hauteur intérieure.
216		const viewportBorderHeight = 1
217		contentHeight := max((availableHeight-1)-viewportBorderHeight, 1)
218		if view, ok := a.views[a.currentView]; ok {
219			updatedView, _ := view.Update(tea.WindowSizeMsg{Width: width, Height: contentHeight})
220			a.views[a.currentView] = updatedView
221		}
222	}
