// truncateToWidth cuts a line to at most `width` cells. lipgloss.MaxWidth coupe
// en tenant compte des séquences ANSI : couper à la main baverait à l'intérieur
// d'un échappement et sur toutes les lignes suivantes (Rule 122).
func truncateToWidth(line string, width int) string {
	if lipgloss.Width(line) <= width {
		return line
	}
	return lipgloss.NewStyle().MaxWidth(width).Render(line)
