package dashboard

import (
	"fmt"
	"runtime"
	"strings"

	"github.com/anthnel/devdesk/internal/status"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// section is one titled box of the dashboard. Les sections sont déclarées dans
// une table plutôt qu'en autant de méthodes render*Section : c'est ce qui rend
// la règle « une section déclare sa hauteur et la remplit » vérifiable pour
// toutes d'un coup (§3.19 phase 1).
type section struct {
	title string
	// render returns the box's content lines. Il en retourne le *même nombre*
	// quel que soit l'état des données — c'est le contrat que
	// TestEverySectionKeepsItsHeightWhateverItsState vérifie.
	render func(m Model, width int) []string
}

// labelWidth aligns every label column of every box on one width.
const labelWidth = 11

// overviewSections returns the four boxes of the Overview tab, in reading
// order: the two text boxes first, then the two that carry a chart.
//
// Le regroupement est par question posée, pas par source de données — d'où
// deux fusions : workspaces rejoint GitLab (l'explorer crée, workspaces
// réconcilie : un seul sujet vu des deux bouts) et les outils rejoignent Host
// (ce sont les binaires de cette machine, mesurés par la même sonde).
func overviewSections() []section {
	return []section{
		{title: theme.IconGitlab + " Code", render: renderCodeSection},
		{title: theme.IconSecurity + " Health", render: renderHealthSection},
		{title: theme.IconServer + " " + hostLabel(), render: renderHostSection},
		{title: theme.IconDocker + " Docker (VM)", render: renderDockerSection},
	}
}

// resourceSections returns the boxes of the Resources tab — inline in the third
// column at `wide`. Elles n'existent que parce qu'aucune vue ne les montre :
// il n'y a pas de :host, et :containers montre un conteneur, pas la machine.
func resourceSections() []section {
	return []section{
		{title: theme.IconArrowDown + " Network", render: renderNetworkSection},
		{title: theme.IconDirectory + " Storage", render: renderStorageSection},
	}
}

// hostLabel names the measurement point rather than the machine. gopsutil reads
// the OS dk runs on, while docker stats reads inside the Docker Desktop VM:
// les deux sont vrais et ne s'additionnent pas.
func hostLabel() string {
	switch runtime.GOOS {
	case "windows":
		return "Host (Windows)"
	case "darwin":
		return "Host (macOS)"
	default:
		return "Host (Linux)"
	}
}

func renderCodeSection(m Model, width int) []string {
	sessionLine := theme.DimStyle.Render("n/a") + theme.Bg("  not connected")
	if m.shared.IsAuthenticated && m.shared.CurrentUser != nil {
		sessionLine = theme.StatusOKStyle.Render(theme.IconOK) +
			theme.Bg(" ") + theme.PrimaryColorStyle.Bold(true).Render(m.shared.CurrentUser.Username)
	}

	mrs, review, issues := unknownValue, unknownValue, unknownValue
	if m.gitlabStats != nil {
		mrs = countValue(m.gitlabStats.AssignedMRs)
		review = countValue(m.gitlabStats.ReviewMRs)
		issues = countValue(m.gitlabStats.AssignedIssues)
	}

	workspaces := unknownValue
	if !m.loadingWorkspaces {
		workspaces = countValue(m.workspaceCount)
	}

	return []string{
		sessionLine,
		row("Merge req.", mrs+theme.Bg(" assigned  ")+review+theme.Bg(" to review")),
		row("Issues", issues+theme.Bg(" assigned")),
		theme.Bg(""),
		row("Workspaces", workspaces),
		theme.DimStyle.Render(truncatePath(m.config.App.WorkspacesDir, width-labelWidth)),
	}
}

func renderHealthSection(m Model, _ int) []string {
	monitors, certs := unknownValue, unknownValue
	if !m.loadingServices {
		monitors = statusSummary(m.filterComponents(false))
		certs = statusSummary(m.filterComponents(true))
	}

	return []string{
		row("Monitors", monitors),
		row("Certs", certs),
		theme.Bg(""),
		// Phase 4 : lus depuis ImageScanCache et WorkspaceScanCache (Rule 126).
		row("Scanned", unknownValue),
		row("Critical", unknownValue),
		row("Oldest", unknownValue),
	}
}

func renderHostSection(m Model, _ int) []string {
	tools := unknownValue
	if !m.loadingTools {
		tools = toolsSummary(m.tools)
	}

	return []string{
		// Phase 2 : gopsutil. La moyenne de charge n'est affichée nulle part —
		// load.Avg() retourne {0,0,0} avec err=nil sur Windows, donc une valeur
		// indiscernable d'une donnée.
		row("CPU", unknownValue),
		row("RAM", unknownValue),
		theme.Bg(""),
		row("Disk", unknownValue),
		theme.Bg(""),
		row("Tools", tools),
	}
}

func renderDockerSection(m Model, _ int) []string {
	containers := unavailableValue
	if m.loadingDocker {
		containers = unknownValue
	} else if m.dockerStats != nil && m.dockerStats.Available {
		d := m.dockerStats
		containers = countValue(d.Running+d.Stopped+d.Paused) +
			theme.Bg(" total  ") + countValue(d.Running) + theme.Bg(" running")
	}

	images, volumes := unavailableValue, unavailableValue
	if m.loadingOCI {
		images, volumes = unknownValue, unknownValue
	} else if m.ociStats != nil && m.ociStats.Available {
		images = sizedCount(m.ociStats.ImagesCount, m.ociStats.ImagesSize)
		volumes = sizedCount(m.ociStats.VolumesCount, m.ociStats.VolumesSize)
	}

	return []string{
		row("Containers", containers),
		row("Images", images),
		row("Volumes", volumes),
		theme.Bg(""),
		// Phase 2 : docker stats, sur son horloge propre (≈ 2 s par appel).
		row("CPU / RAM", unknownValue),
		row("Reclaim", unknownValue),
	}
}

func renderNetworkSection(_ Model, _ int) []string {
	return []string{
		// Phase 2 : net.IOCounters est cumulatif, donc le premier échantillon
		// n'a pas de débit — il affiche `-`, pas `0`.
		row("RX", unknownValue),
		row("TX", unknownValue),
		theme.Bg(""),
		row("Interfaces", unknownValue),
		theme.Bg(""),
		theme.Bg(""),
	}
}

func renderStorageSection(m Model, _ int) []string {
	workspaceDisk := unknownValue
	if !m.loadingWorkspaces && m.workspaceDisk != "" {
		workspaceDisk = theme.Bg(m.workspaceDisk)
	}

	return []string{
		row("Workspaces", workspaceDisk),
		// Phase 2 : disk.Usage, 1 ms — le meilleur rapport valeur/coût du
		// dashboard, et la mesure qui manque aujourd'hui.
		row("Free", unknownValue),
		row("Docker root", unknownValue),
		theme.Bg(""),
		row("Reclaimable", unknownValue),
		theme.Bg(""),
	}
}

// Value states (§3.19). Trois états, pas deux : `-` n'est pas `0`, et une
// source indisponible garde ses libellés au lieu de les remplacer.
var (
	unknownValue     = theme.DimStyle.Render("-")
	unavailableValue = theme.DimStyle.Render("n/a")
)

// row renders one "label  value" line, aligned on labelWidth.
func row(label, value string) string {
	padded := label
	if len(label) < labelWidth {
		padded = label + strings.Repeat(" ", labelWidth-len(label))
	}
	return theme.Bg(padded) + value
}

// countValue renders a measured count: a zero informs no one, so it stays dim
// and the colour is spent on what is worth spotting (Rule 122's discipline).
func countValue(n int) string {
	if n > 0 {
		return theme.PrimaryColorStyle.Bold(true).Render(fmt.Sprintf("%d", n))
	}
	return theme.DimStyle.Render("0")
}

// sizedCount renders "N (size)", the size dim.
func sizedCount(n int, size string) string {
	if size == "" {
		return countValue(n)
	}
	return countValue(n) + theme.DimStyle.Render(" ("+size+")")
}

// statusSummary renders "✓ N  ✗ N" for a set of components, hiding neither
// half: a missing failure count reads as zero failures.
func statusSummary(components []status.ComponentStatus) string {
	if len(components) == 0 {
		return theme.DimStyle.Render("none configured")
	}
	ok, down, errCount := countStatuses(components)
	out := theme.StatusOKStyle.Render(theme.IconOK+" ") + theme.Bg(fmt.Sprintf("%d", ok))
	if down > 0 {
		out += theme.Bg("  ") + theme.StatusDownStyle.Render(theme.IconError+" ") + theme.Bg(fmt.Sprintf("%d", down))
	}
	if errCount > 0 {
		out += theme.Bg("  ") + theme.StatusErrorStyle.Render(theme.IconWarning+" ") + theme.Bg(fmt.Sprintf("%d", errCount))
	}
	return out
}

// toolsSummary renders "N of M available".
func toolsSummary(tools []shared_ToolInfo) string {
	if len(tools) == 0 {
		return unavailableValue
	}
	available := 0
	for _, t := range tools {
		if t.Available {
			available++
		}
	}
	return countValue(available) + theme.Bg(fmt.Sprintf(" of %d available", len(tools)))
}

// truncatePath keeps a path's tail, which is the half that identifies it.
func truncatePath(path string, width int) string {
	if width < 4 || len(path) <= width {
		return path
	}
	return "…" + path[len(path)-width+1:]
}

