// Package metrics samples the machine DevDesk runs on. Il possède
// l'échantillonnage et le calcul des débits ; l'affichage appartient à la vue.
//
// Rien ici ne garde d'état : un débit se calcule entre deux relevés cumulatifs,
// et le relevé précédent **voyage avec le message** plutôt que d'être stocké
// dans le package. Un `Cmd` Bubble Tea ne doit modifier aucun état partagé
// (Rule 110), et deux échantillonnages qui se chevauchent sur un état de
// package produiraient un débit calculé contre le mauvais instant.
package metrics

import "time"

// HostSample is one reading of the host.
type HostSample struct {
	Taken time.Time

	CPUPercent float64
	MemPercent float64
	MemUsed    uint64
	MemTotal   uint64

	// NetRXPerSec and NetTXPerSec are bytes per second, and mean nothing unless
	// HasRate is true: net.IOCounters is cumulative, so the first reading after
	// a start has nothing to subtract from. La vue affiche `-`, pas `0`.
	NetRXPerSec float64
	NetTXPerSec float64
	HasRate     bool

	// OK is false when the host could not be read at all.
	OK bool
}

// Counters is the cumulative network reading a rate is measured against. Elle
// est rendue avec l'échantillon et repassée au suivant.
type Counters struct {
	RX    uint64
	TX    uint64
	At    time.Time
	Valid bool
}

// rate returns the per-second deltas between two cumulative readings.
//
// Il refuse trois situations plutôt que d'inventer un nombre :
//   - pas de relevé précédent — le premier échantillon n'a pas de débit ;
//   - un compteur qui recule — une interface réinitialisée, un rollover : la
//     soustraction donnerait un débit négatif, qui n'existe pas ;
//   - un intervalle nul ou négatif — une division par zéro, ou une horloge qui
//     a reculé.
//
// Dans les trois cas l'échantillon est *abandonné*, pas rendu à zéro : zéro est
// une mesure, et celle-ci n'a pas eu lieu.
func rate(prev, cur Counters) (rx, tx float64, ok bool) {
	if !prev.Valid || !cur.Valid {
		return 0, 0, false
	}
	if cur.RX < prev.RX || cur.TX < prev.TX {
		return 0, 0, false
	}
	elapsed := cur.At.Sub(prev.At).Seconds()
	if elapsed <= 0 {
		return 0, 0, false
	}
	return float64(cur.RX-prev.RX) / elapsed, float64(cur.TX-prev.TX) / elapsed, true
}

// DiskUsage is one filesystem's free space.
type DiskUsage struct {
	Path        string
	Free        uint64
	Total       uint64
	UsedPercent float64
	OK          bool
}

package metrics

import (
	"log"
	"time"

	"github.com/shirou/gopsutil/v4/cpu"
	"github.com/shirou/gopsutil/v4/disk"
	"github.com/shirou/gopsutil/v4/mem"
	"github.com/shirou/gopsutil/v4/net"
)

// SampleHost reads the host once and returns the reading plus the cumulative
// counters the *next* call must be given.
//
// **La moyenne de charge n'est lue nulle part, sur aucune plateforme.** Sur
// Windows `load.Avg()` retourne `{0, 0, 0}` avec `err == nil` : elle n'échoue
// pas, elle produit un nombre indiscernable d'une donnée, et un zéro se lit
// comme « la machine est au repos ». Une métrique présente sur deux
// plateformes sur trois est pire qu'une métrique absente partout, parce que son
// absence ne se voit pas.
func SampleHost(prev Counters) (HostSample, Counters) {
	s := HostSample{Taken: time.Now()}

	// cpu.Percent(0, …) calcule depuis l'appel précédent au lieu de bloquer
	// pendant l'intervalle — un cpu.Percent(500ms) coûterait 501 ms à chaque
	// tick de l'horloge rapide.
	if pct, err := cpu.Percent(0, false); err == nil && len(pct) > 0 {
		s.CPUPercent = pct[0]
		s.OK = true
	} else if err != nil {
		log.Printf("ERROR [metrics/host] cpu.Percent: %v", err)
	}

	if vm, err := mem.VirtualMemory(); err == nil && vm != nil {
		s.MemPercent = vm.UsedPercent
		s.MemUsed = vm.Used
		s.MemTotal = vm.Total
		s.OK = true
	} else if err != nil {
		log.Printf("ERROR [metrics/host] mem.VirtualMemory: %v", err)
	}

	next := readNetCounters(s.Taken)
	if rx, tx, ok := rate(prev, next); ok {
		s.NetRXPerSec, s.NetTXPerSec, s.HasRate = rx, tx, true
	}

	return s, next
}

// readNetCounters sums every interface's cumulative byte counters.
func readNetCounters(at time.Time) Counters {
	stats, err := net.IOCounters(false)
	if err != nil || len(stats) == 0 {
		if err != nil {
			log.Printf("ERROR [metrics/host] net.IOCounters: %v", err)
		}
		return Counters{At: at}
	}
	return Counters{RX: stats[0].BytesRecv, TX: stats[0].BytesSent, At: at, Valid: true}
}

// Disk reports free space on the filesystem holding path. Mesuré à 1 ms, contre
// plusieurs secondes pour un `du -sh` de l'arborescence : la question utile est
// « combien reste-t-il », pas « combien pèse cet arbre ».
func Disk(path string) DiskUsage {
	usage, err := disk.Usage(path)
	if err != nil || usage == nil {
		if err != nil {
			log.Printf("ERROR [metrics/host] disk.Usage(%q): %v", path, err)
		}
		return DiskUsage{Path: path}
	}
	return DiskUsage{
		Path:        path,
		Free:        usage.Free,
		Total:       usage.Total,
		UsedPercent: usage.UsedPercent,
		OK:          true,
	}
}

package metrics

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// Le calcul des débits est pur : pas de Docker, pas de réseau, pas de terminal.
// C'est aussi l'endroit où une réponse fausse se voit le moins à l'écran — un
// débit plausible et faux ressemble à un débit.

func at(seconds int) time.Time {
	return time.Date(2026, 8, 14, 12, 0, seconds, 0, time.UTC)
}

// TestTheFirstSampleHasNoRate — net.IOCounters est cumulatif, donc le premier
// relevé n'a rien à soustraire. La vue doit afficher `-`, pas `0`.
func TestTheFirstSampleHasNoRate(t *testing.T) {
	cur := Counters{RX: 1000, TX: 500, At: at(1), Valid: true}

	if _, _, ok := rate(Counters{}, cur); ok {
		t.Error("a counter read once produced a rate — there is nothing to subtract from")
	}
}

func TestARateIsBytesPerSecond(t *testing.T) {
	prev := Counters{RX: 1000, TX: 500, At: at(0), Valid: true}
	cur := Counters{RX: 3000, TX: 1500, At: at(2), Valid: true}

	rx, tx, ok := rate(prev, cur)
	if !ok {
		t.Fatal("two valid readings two seconds apart produced no rate")
	}
	if rx != 1000 || tx != 500 {
		t.Errorf("rate = %.0f RX / %.0f TX, want 1000 / 500", rx, tx)
	}
}

// TestARateSurvivesACounterReset — une interface réinitialisée fait reculer le
// compteur. Rendre la soustraction telle quelle donnerait un débit négatif ;
// l'échantillon est abandonné.
func TestARateSurvivesACounterReset(t *testing.T) {
	prev := Counters{RX: 9000, TX: 9000, At: at(0), Valid: true}
	reset := Counters{RX: 12, TX: 8, At: at(1), Valid: true}

	rx, tx, ok := rate(prev, reset)
	if ok {
		t.Errorf("a counter that went backwards produced a rate of %.0f / %.0f", rx, tx)
	}
}

func TestARateNeedsTimeToHavePassed(t *testing.T) {
	prev := Counters{RX: 1000, At: at(1), Valid: true}

	if _, _, ok := rate(prev, Counters{RX: 2000, At: at(1), Valid: true}); ok {
		t.Error("two readings at the same instant produced a rate — that is a division by zero")
	}
	if _, _, ok := rate(prev, Counters{RX: 2000, At: at(0), Valid: true}); ok {
		t.Error("a clock that went backwards produced a rate")
	}
}

// TestAnUnreadableCounterYieldsNoRate — readNetCounters returns an invalid
// Counters when the host cannot be read, and an invalid reading is not a zero
// reading.
func TestAnUnreadableCounterYieldsNoRate(t *testing.T) {
	prev := Counters{RX: 1000, At: at(0), Valid: true}

	if _, _, ok := rate(prev, Counters{At: at(1)}); ok {
		t.Error("an unreadable counter produced a rate")
	}
}

// TestLoadAverageIsDisplayedNowhere pins the Windows trap: load.Avg() returns
// {0, 0, 0} with a nil error there, so it does not fail — it produces a number
// that reads as "idle". Ce test existe pour que personne ne la rajoute au
// motif qu'elle « marche sous Linux ».
func TestLoadAverageIsDisplayedNowhere(t *testing.T) {
	roots := []string{".", filepath.Join("..", "ui", "dashboard")}

	for _, root := range roots {
		entries, err := os.ReadDir(root)
		if err != nil {
			t.Fatalf("reading %s: %v", root, err)
		}
		for _, e := range entries {
			if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") || strings.HasSuffix(e.Name(), "_test.go") {
				continue
			}
			body, err := os.ReadFile(filepath.Join(root, e.Name()))
			if err != nil {
				t.Fatalf("reading %s: %v", e.Name(), err)
			}
			for _, banned := range []string{"load.Avg", "gopsutil/v4/load", "LoadAvg"} {
				if strings.Contains(string(body), banned) {
					t.Errorf("%s/%s mentions %q — load average is displayed on no platform",
						root, e.Name(), banned)
				}
			}
		}
	}
}

// SampleHost talks to the host, so this asserts only what holds on any machine:
// it returns without panicking, and the counters it hands back are what the
// next call must be given.
func TestSampleHostReturnsTheCountersForTheNextCall(t *testing.T) {
	first, counters := SampleHost(Counters{})

	if first.HasRate {
		t.Error("the first sample reported a rate")
	}
	if first.Taken.IsZero() {
		t.Error("the sample is not stamped, so its age cannot be shown")
	}
	if !counters.Valid {
		t.Skip("this host exposes no network counters; the rate path cannot be exercised here")
	}

	second, _ := SampleHost(counters)
	if !second.HasRate {
		t.Error("a second sample against valid counters produced no rate")
	}
	if second.NetRXPerSec < 0 || second.NetTXPerSec < 0 {
		t.Errorf("a negative throughput reached the caller: %.0f / %.0f", second.NetRXPerSec, second.NetTXPerSec)
	}
}

func TestDiskReportsFreeSpaceOrSaysItCouldNot(t *testing.T) {
	usage := Disk(t.TempDir())
	if !usage.OK {
		t.Skip("the temp directory's filesystem could not be read")
	}
	if usage.Total == 0 {
		t.Error("a readable filesystem reported a total of zero")
	}
	if usage.Free > usage.Total {
		t.Errorf("free %d exceeds total %d", usage.Free, usage.Total)
	}
}

// A path that does not exist must report OK=false rather than a zeroed usage
// that reads as a full disk.
func TestAnUnreadablePathIsNotAFullDisk(t *testing.T) {
	usage := Disk(filepath.Join(t.TempDir(), "no", "such", "place"))

	if usage.OK {
		t.Error("a missing path reported a usable reading")
	}
	if usage.UsedPercent != 0 || usage.Total != 0 {
		t.Errorf("a failed reading carries numbers: %+v", usage)
	}
}

