// expandHome resolves a leading ~/ against the user's home directory.
func expandHome(dir string) string {
	if len(dir) >= 2 && dir[:2] == "~/" {
		home, _ := os.UserHomeDir()
		return filepath.Join(home, dir[2:])
	}
	return dir
}

