// calculateDiskUsage returns human-readable disk usage for a directory
func calculateDiskUsage(dir string) string {
	cmd := exec.Command("du", "-sh", dir)
	out, err := cmd.Output()
	if err != nil {
		return ""
	}
	parts := strings.Fields(string(out))
	if len(parts) >= 1 {
		return parts[0]
	}
	return ""
}

