// Rend le dashboard complet (header, règle de titre, grille, footer) en HTML,
// à la taille passée par ZZ_SIZE. Jetable : sert à envoyer une capture.
func TestZZScreenshot(t *testing.T) {
	out := os.Getenv("ZZ_OUT")
	if out == "" {
		t.Skip("set ZZ_OUT to render a screenshot")
	}

	restore := lipgloss.ColorProfile()
	lipgloss.SetColorProfile(termenv.TrueColor)
	t.Cleanup(func() { lipgloss.SetColorProfile(restore) })

	width, height := 250, 60
	app := newWithSize(testConfig(), width, height)
	app.currentView = command.ViewDashboard
	app.resize(width, height)

	// Real readings from this machine, sampled over a couple of seconds so the
	// charts show something that actually happened.
	counters := metrics.Counters{}
	for range 60 {
		var sample metrics.HostSample
		sample, counters = metrics.SampleHost(counters)
		send(t, app, dashboard.HostSampleMsg{Sample: sample, Counters: counters})
		time.Sleep(40 * time.Millisecond)
	}

	send(t, app,
		dashboard.DiskUsageMsg{Workspaces: metrics.Disk(".")},
		dashboard.DockerMetricsMsg{Aggregate: docker.FetchAggregateMetrics()},
		dashboard.OCIStatsMsg{Stats: sharedOCI()},
		dashboard.DockerStatsMsg{Stats: sharedDocker()},
		dashboard.WorkspaceStatsMsg{Count: 6},
	)

	if err := os.WriteFile(out, []byte(toHTML(app.View())), 0o644); err != nil {
		t.Fatalf("writing %s: %v", out, err)
	}
	t.Logf("wrote %s", out)
}

func send(t *testing.T, a *App, msgs ...tea.Msg) {
	t.Helper()
	view := a.views[command.ViewDashboard]
	for _, msg := range msgs {
		view, _ = view.Update(msg)
	}
	a.views[command.ViewDashboard] = view
}

func sharedOCI() (s sharedOCIStats) { return docker.FetchOCIStats() }

func sharedDocker() docker.ContainerStats { return docker.FetchContainerStats() }

type sharedOCIStats = docker.OCIStats

// ── ANSI to HTML ─────────────────────────────────────────────────────────────

var sgr = regexp.MustCompile(`\x1b\[([0-9;]*)m`)

func toHTML(frame string) string {
	var b strings.Builder
	b.WriteString(`<div style="background:#1e1e2e;padding:16px;overflow-x:auto">` +
		`<pre style="margin:0;font:12px/1.25 'Cascadia Code','JetBrains Mono',Consolas,monospace;` +
		`background:#1e1e2e;color:#cdd6f4;white-space:pre">`)

	for _, line := range strings.Split(frame, "\n") {
		b.WriteString(lineToHTML(line))
		b.WriteByte('\n')
	}
	b.WriteString("</pre></div>")
	return b.String()
}

func lineToHTML(line string) string {
	var b strings.Builder
	open := false
	last := 0

	for _, loc := range sgr.FindAllStringSubmatchIndex(line, -1) {
		b.WriteString(html.EscapeString(line[last:loc[0]]))
		last = loc[1]

		if open {
			b.WriteString("</span>")
			open = false
		}
		if style := styleOf(line[loc[2]:loc[3]]); style != "" {
			b.WriteString(`<span style="` + style + `">`)
			open = true
		}
	}
	b.WriteString(html.EscapeString(line[last:]))
	if open {
		b.WriteString("</span>")
	}
	return b.String()
}

// styleOf turns one SGR parameter list into CSS. Only what lipgloss emits in
// TrueColor is handled: reset, bold, and 24-bit fore/background.
func styleOf(params string) string {
	fields := strings.Split(params, ";")
	var css []string

	for i := 0; i < len(fields); i++ {
		switch fields[i] {
		case "", "0":
			return ""
		case "1":
			css = append(css, "font-weight:600")
		case "38", "48":
			if i+4 < len(fields) && fields[i+1] == "2" {
				prop := "color"
				if fields[i] == "48" {
					prop = "background"
				}
				css = append(css, fmt.Sprintf("%s:rgb(%s,%s,%s)", prop,
					num(fields[i+2]), num(fields[i+3]), num(fields[i+4])))
				i += 4
			}
		}
	}
	return strings.Join(css, ";")
}

func num(s string) string {
	if _, err := strconv.Atoi(s); err != nil {
		return "0"
	}
	return s
}

