// ── ANSI to HTML ─────────────────────────────────────────────────────────────

var sgr = regexp.MustCompile(`\x1b\[([0-9;]*)m`)

func toHTML(frame string) string {
	var b strings.Builder
	b.WriteString(`<div style="background:#1e1e2e;padding:16px;overflow-x:auto">` +
		`<pre style="margin:0;font:12px/1.25 'Cascadia Code','JetBrains Mono',Consolas,monospace;` +
		`background:#1e1e2e;color:#cdd6f4;white-space:pre">`)

	for _, line := range strings.Split(frame, "\n") {
		b.WriteString(lineToHTML(line))
		b.WriteByte('\n')
	}
	b.WriteString("</pre></div>")
	return b.String()
}

func lineToHTML(line string) string {
	var b strings.Builder
	open := false
	last := 0

	for _, loc := range sgr.FindAllStringSubmatchIndex(line, -1) {
		b.WriteString(html.EscapeString(line[last:loc[0]]))
		last = loc[1]

		if open {
			b.WriteString("</span>")
			open = false
		}
		if style := styleOf(line[loc[2]:loc[3]]); style != "" {
			b.WriteString(`<span style="` + style + `">`)
			open = true
		}
	}
	b.WriteString(html.EscapeString(line[last:]))
	if open {
		b.WriteString("</span>")
	}
	return b.String()
}

func styleOf(params string) string {
	fields := strings.Split(params, ";")
	var css []string

	for i := 0; i < len(fields); i++ {
		switch fields[i] {
		case "", "0":
			return ""
		case "1":
			css = append(css, "font-weight:600")
		case "38", "48":
			if i+4 < len(fields) && fields[i+1] == "2" {
				prop := "color"
				if fields[i] == "48" {
					prop = "background"
				}
				css = append(css, fmt.Sprintf("%s:rgb(%s,%s,%s)", prop,
					num(fields[i+2]), num(fields[i+3]), num(fields[i+4])))
				i += 4
			}
		}
	}
	return strings.Join(css, ";")
}

func num(s string) string {
	if _, err := strconv.Atoi(s); err != nil {
		return "0"
	}
	return s
}

