// statusBranches renders one node per state. Les trois sont toujours là, y
// compris à zéro : une branche absente se lit comme un état qu'on ne surveille
// pas, et c'est l'inverse de ce qu'un zéro veut dire.
func statusBranches(components []status.ComponentStatus, loading bool) []string {
	if loading {
		return []string{
			branch(false, "up", unknownValue),
			branch(false, "down", unknownValue),
			branch(true, "error", unknownValue),
		}
	}
	if len(components) == 0 {
		return []string{
			branch(true, "none configured", theme.Bg("")),
			theme.Bg(""),
			theme.Bg(""),
		}
	}

	ok, down, errCount := countStatuses(components)
	return []string{
		branch(false, "up", theme.StatusOKStyle.Render(theme.IconOK)+theme.Bg(" ")+countValue(ok)),
		branch(false, "down", failureCount(down, theme.StatusDownStyle.Render(theme.IconError))),
		branch(true, "error", failureCount(errCount, theme.StatusErrorStyle.Render(theme.IconWarning))),
	}
}

// failureCount keeps its icon dim while the count is zero: une croix rouge sur
// « 0 down » apprend la couleur au lecteur au lieu de l'alerter.
func failureCount(n int, icon string) string {
	if n == 0 {
		return theme.DimStyle.Render(theme.IconOK) + theme.Bg(" ") + countValue(0)
	}
	return icon + theme.Bg(" ") + severityCount(n)
}

// postureBranches renders one family's tally as three nodes.
func postureBranches(p posture, side postureSide) []string {
	if !p.Read {
		return []string{
			branch(false, "scanned", unknownValue),
			branch(false, "critical", unknownValue),
			branch(true, "oldest", unknownValue),
		}
	}
	return []string{
		branch(false, "scanned", countValue(side.Targets)+theme.Bg(" targets")),
		branch(false, "critical", severityCount(side.Critical)+theme.Bg("  ")+
			severityCount(side.High)+theme.DimStyle.Render(" high")),
		branch(true, "oldest", scanAge(side)),
	}
}

