	// À `wide`, la boîte devient deux arbres, et la séparation est celle des
	// deux moitiés de §3.16 : l'explorer crée ce qui n'existe pas — la forge —
	// et workspaces réconcilie ce qui existe — le disque. Chacune a sa question,
	// donc chacune a sa racine, et les faits de la forge cessent de flotter
	// au-dessus d'un arbre auquel ils n'appartiennent pas.
	//
	// Les compteurs y deviennent des branches : « 0 assigned  0 to review » sur
	// une ligne demande de relire la phrase pour savoir lequel est lequel, deux
	// nœuds le disent en les alignant.
	pathWidth := theme.BoxContentWidth(width) - treeValueColumn
	return []string{
		theme.Bg("GitLab"),
		branch(false, "user", sessionLine),
		branch(false, "host", theme.Bg(forgeHost(m.config.GitLab.URL))),
		branch(false, "issues", issues+theme.Bg(" assigned")),
		branch(false, "MR assigned", mrs),
		branch(true, "MR to review", review),
		theme.Bg("Workspaces"),
		branch(false, "repositories", workspaces),
		branch(false, "path", theme.DimStyle.Render(truncatePath(m.config.App.WorkspacesDir, pathWidth))),
		branch(true, "disk", diskUsed(m.wsDisk)),
	}
}

// diskUsed says how full the volume holding the workspaces is.
//
// **Ce n'est pas la taille de l'arborescence.** La mesurer demande un `du`,
// dont le coût grandit avec les données de l'utilisateur et qui a justement été
// retiré du tour lent (§3.19) ; le volume, lui, répond en 1 ms. C'est aussi la
// question qui se décide : une arborescence de 40 Go n'appelle rien, un volume
// à 97 % appelle quelque chose.
//
// Il complète le `Disk` de la boîte Host plutôt que de le répéter : celui-ci dit
// ce qui reste, celui-là ce qui est pris, et c'est le second qui a sa place sous
// le chemin dont il parle.
func diskUsed(d metrics.DiskUsage) string {
	if !d.OK {
		return unknownValue
	}
	return theme.Bg(humanBytes(d.Used)) +
		theme.DimStyle.Render(fmt.Sprintf(" used  %.0f%%", d.UsedPercent))
}

