155	// rescanOneCmd rescans a single target and writes the result through to both
156	// the counts cache and the stored result, so the row and `enter` agree.
157	func rescanOneCmd(job inventoryScanJob, opts scan.ScanOptions, sem chan struct{}) tea.Cmd {
158		return func() tea.Msg {
159			sem <- struct{}{}
160			defer func() { <-sem }()
161	
162			targetType := scan.TargetImage
163			if job.Kind == kindRepo {
164				targetType = scan.TargetDirectory
165			}
166			result, err := scan.NewScanner(opts).Scan(context.Background(), job.Name, targetType)
167			if err != nil {
168				log.Printf("ERROR [security/inventory] rescan %s: %v", job.Name, err)
169				return InventoryScanFinishedMsg{Name: job.Name, Err: err}
170			}
171			// Scan() reports scanner failures in result.Errors rather than as an
172			// error. Every scanner having failed is not an empty inventory row, it
173			// is a row that could not be produced.
174			if len(result.Errors) > 0 && result.TotalFindings() == 0 {
175				combined := strings.Join(result.Errors, "; ")
176				log.Printf("ERROR [security/inventory] rescan errors for %s: %s", job.Name, combined)
177				return InventoryScanFinishedMsg{Name: job.Name, Err: errors.New(combined)}
178			}
179	
180			storeRescan(job, result)
181			return InventoryScanFinishedMsg{Name: job.Name, Counts: result.Counts, ScannedAt: result.EndTime}
182		}
183	}
