234	func (m *Model) formatScanColumns(entry Entry, frame string) (sensitive, c, h, med, l, scanned string) {
235		dash := "-"
236		empty := ""
237	
238		if entry.IsGitRepo {
239			if m.scanningPaths[entry.Path] {
240				return empty, dash, dash, dash, dash, frame + " scanning"
241			}
242			scanEntry, ok := m.scanCache[entry.Path]
243			if !ok {
244				return dash, dash, dash, dash, dash, dash
245			}
246			return formatSecrets(scanEntry.Sensitive, true),
247				fmt.Sprintf("%d", scanEntry.Critical),
248				fmt.Sprintf("%d", scanEntry.High),
249				fmt.Sprintf("%d", scanEntry.Medium),
250				fmt.Sprintf("%d", scanEntry.Low),
251				theme.IconPending + " " + timeAgo(scanEntry.ScannedAt)
252		}
253	
254		// Files are not scannable — return empty columns
255		if !entry.IsDir {
256			return empty, empty, empty, empty, empty, empty
257		}
258	
259		// Directory: aggregate sub-repos
260		if len(entry.SubRepoPaths) == 0 {
261			return theme.IconWorkspaceUnknown, empty, empty, empty, empty, empty
262		}
263	
264		// Count how many sub-repos are currently scanning
265		scanningCount := 0
266		for _, repoPath := range entry.SubRepoPaths {
267			if m.scanningPaths[repoPath] {
268				scanningCount++
269			}
270		}
271	
272		var scannedEntries []cache.WorkspaceScanEntry
273		for _, repoPath := range entry.SubRepoPaths {
274			if e, ok := m.scanCache[repoPath]; ok {
275				scannedEntries = append(scannedEntries, e)
276			}
277		}
278	
279		if len(scannedEntries) == 0 && scanningCount == 0 {
280			return dash, empty, empty, empty, empty, dash
281		}
282		if len(scannedEntries) == 0 && scanningCount > 0 {
283			return empty, dash, dash, dash, dash, frame + " scanning"
284		}
285	
286		totalC, totalH, totalM, totalL := 0, 0, 0, 0
287		hasSensitive := false
288		for _, e := range scannedEntries {
289			totalC += e.Critical
290			totalH += e.High
291			totalM += e.Medium
292			totalL += e.Low
293			if e.Sensitive {
294				hasSensitive = true
295			}
296		}
297	
298		scannedCount := len(scannedEntries)
299		totalCount := len(entry.SubRepoPaths)
300		scanned = theme.IconDirectory + " " + fmt.Sprintf("%d/%d", scannedCount, totalCount)
301	
302		return formatSecrets(hasSensitive, scannedCount > 0),
303			fmt.Sprintf("%d", totalC),
304			fmt.Sprintf("%d", totalH),
305			fmt.Sprintf("%d", totalM),
306			fmt.Sprintf("%d", totalL),
307			scanned
308	}
