10	// Size walks a directory and adds up what its files occupy.
11	//
12	// **C'est le seul appel du package dont le coût grandit avec les données de
13	// l'utilisateur** : il lit chaque entrée de chaque dossier. Il tourne donc sur
14	// l'horloge lente, sur la goroutine d'un Cmd, et jamais deux à la fois — voir
15	// Model.measuringSize, qui est là pour ça et pour rien d'autre.
16	//
17	// Les liens symboliques ne sont pas suivis : WalkDir lit le lien et non sa
18	// cible, ce qui évite d'un même geste les cycles et le double comptage d'un
19	// dossier déjà dans l'arbre.
20	//
21	// Rien n'est exclu du parcours, `.git` compris : un dépôt cloné coûte son
22	// historique autant que son arbre de travail, et c'est souvent l'historique qui
23	// pèse. La question posée est « combien ce dossier prend », pas « combien de
24	// code il contient ».
25	func Size(path string) TreeSize {
26		out := TreeSize{Path: path}
27		if path == "" {
28			return out
29		}
30	
31		// La racine est vérifiée à part : sans ça, un chemin illisible rend une
32		// mesure « réussie » à zéro octet, ce qui se lit comme un dossier vide.
33		if _, err := os.Stat(path); err != nil {
34			log.Printf("ERROR [metrics/tree] stat %q: %v", path, err)
35			return out
36		}
37	
38		err := filepath.WalkDir(path, func(_ string, d fs.DirEntry, err error) error {
39			if err != nil {
40				// Un dossier refusé ou disparu en cours de route n'arrête pas la
41				// mesure : il la rend partielle.
42				out.Partial = true
43				if d != nil && d.IsDir() {
44					return fs.SkipDir
45				}
46				return nil
47			}
48			if d.IsDir() {
49				return nil
50			}
51			info, err := d.Info()
52			if err != nil {
53				out.Partial = true
54				return nil
55			}
56			if size := info.Size(); size > 0 {
57				out.Bytes += uint64(size)
58			}
59			return nil
60		})
61		if err != nil {
62			log.Printf("ERROR [metrics/tree] walking %q: %v", path, err)
63			return TreeSize{Path: path}
64		}
65	
66		out.OK = true
67		return out
68	}
