// withTrueColor forces the renderer to emit escape sequences for the duration
// of one test. Without it lipgloss detects no TTY, falls back to the Ascii
// profile and strips every colour — which would make every assertion in this
// file pass whatever the code does.
func withTrueColor(t *testing.T) {
	t.Helper()
	previous := lipgloss.ColorProfile()
	lipgloss.SetColorProfile(termenv.TrueColor)
	t.Cleanup(func() { lipgloss.SetColorProfile(previous) })
}

// visible returns what a string puts on screen, escape sequences removed. The
// sequences are exactly what these tests are about, so the text has to be
// recoverable without them.
func visible(s string) string {
	var out strings.Builder

150	
151	// ── The rest of the line ─────────────────────────────────────────────────────
152	
153	// lipgloss does not inherit a background (Rule 115), and the app's viewport
154	// style only reaches cells that emit nothing of their own. One coloured cell
155	// would otherwise end its line with a reset and strip the background from
156	// everything to its right — so every cell on an unselected row opens its own
157	// styling, coloured column or not.
158	func TestEveryCellOnAnUnselectedRowOpensItsOwnStyling(t *testing.T) {
