164	
165		if tail := segments[len(segments)-1]; tail != "" {
166			t.Errorf("%q trails the last reset, so it renders with no background", tail)
167		}
168		// Every run between two resets, padding included — lipgloss emits the cell
169		// padding as runs of its own — has to re-open the background, or the line
170		// shows the terminal's own wherever one did not.
171		for i, segment := range segments[:len(segments)-1] {
172			if !strings.HasPrefix(segment, "\x1b[") {
